+/** Chooses a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  let bestLang = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.split(";").map((s) => s.trim());
+    if (!rawTag) continue;
+    const primary = rawTag.split("-")[0].toLowerCase();
+    if (!LANGUAGES.includes(primary)) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(p);
+      if (!m) continue;
+      const n = Number(m[1]);
+      if (!Number.isFinite(n) || n < 0 || n > 1) {
+        valid = false;
+        break;
+      }
+      q = n;
+    }
+    if (valid && q > bestQ) {
+      bestQ = q;
+      bestLang = primary;
+    }
+  }
+  return bestLang ?? fallback;
+}
